// atmosphere tunables (textures: npm run atmos -> public/maps/atmos/)
export const ATMOS = {
  paperOpacity: 0.4,    // paper grain, multiplied over the map
  paperTile: 256,       // css px per paper tile at 1x zoom
  edgeBurn: 0.85,       // alpha of the burnt edge (fades into the page background)
  edgeSize: 7,          // burnt edge width, % of the map
  vignette: 0.5,        // screen-space vignette darkness
  light: 0.16,          // screen-space warm candle glow from the top-left (static; the vignette flickers)
  cloudOpacity: 0.75,   // clouds at 1x zoom (they hug the frame, clear of names/banners)
  cloudFadeStart: 1,    // clouds start fading at this scale...
  cloudFadeEnd: 2,      // ...and are gone (and hidden) from this scale
  parallax: 1.15,       // clouds pan this much faster than the map (closer to the camera)
  cloudPush: 0.6,       // extra outward spread/growth of clouds by the end of the fade
  shadowOpacity: 0.18,  // drifting cloud shadows on the ground
  driftSeconds: [70, 95, 120], // one full back-and-forth loop per shadow
} as const

// "arrive through the clouds" intro: once per session (sessionStorage "protheka-intro-seen"),
// skipped under prefers-reduced-motion, ?atmos=0 and ?poi= deep links. Any input skips it.
export const INTRO = {
  holdMs: 400,          // dense clouds hold after the map has faded in
  durationMs: 2500,     // clouds part, veil lifts, camera settles
  targetPoi: "capital", // POI id the camera ends centred on (clamped to the map bounds)
  targetScale: 1.2,
  dim: 0.4,             // dark veil over the map at the start
} as const

// depth tilt (Tilt.tsx): the screen-space clouds and candle glow shift against the map with device
// tilt (phones) or the mouse (desktop). Off under prefers-reduced-motion and with ?atmos=0.
export const TILT = {
  cloudRange: 14,       // px: clouds (closest to the camera) shift up to this far
  lightRange: 8,        // px: the candle glow shifts the opposite way (the light source stays put);
                        //     keep <= the 16px padding of .atmos-tilt-pad in globals.css
  smoothing: 180,       // ms: low-pass time constant (higher = floatier)
  recenterSpeed: 4,     // s: the phone's neutral re-centres on how it's being held over about this long
  maxTiltDeg: 20,       // phone tilt away from neutral that reaches the full range
} as const

// ambient life after the intro. All of it pauses while the user moves and while the tab is hidden,
// is off under prefers-reduced-motion (smoke shows one still wisp) and with ?atmos=0.
export const AMBIENT = {
  volcano: { x: 46, y: 62.8 },  // % of map: smoke source = top of the drawn plume above "Kalyunbar"
  smoke: {
    count: 6,                   // wisps (textures wisp-1..6), staggered
    durationS: [6, 10],         // each wisp's loop, spread across this range
    opacity: 0.8,               // peak opacity of the smoke
    width: 4.5,                 // wisp width, % of map width (box is 2:3)
  },
  birds: {
    everyS: [13, 17],           // start-to-start between departures, ~15s (set [15, 15] for exact)
    count: [3, 5],              // birds per flock (randomized); each departure = 2 flocks crossing paths
    flightS: [11, 15],          // time for a flock to cross the map (randomized)
    maxFlocks: 4,               // cap, so departures can't pile up while the animations are paused
  },
  flicker: 0.35,                // candle flicker: the vignette's shadows ease back by up to ~35% as the flame flares
} as const

export type POIKind = "region" | "city" | "landmark"

export type POI = {
  id: string
  name: string
  kind: POIKind
  blurb: string          // one line, shown in the sheet's peek state
  lore: string           // short paragraph
  chapters: string[]     // chapter titles set here
  characters?: string[]
  x: number              // % from left of map
  y: number              // % from top
  minLevel: 1 | 2 | 3    // zoom level at which the pin appears (LVL2 / LVL3)
  storyId: string
}

